import { readFileSync } from "node:fs";
import { join } from "node:path";

// Illustrations generated by scripts/illustrations.mjs, inlined so page CSS can drive their
// draw-on animation from scroll position (see .art-scroll in globals.css). Read once at build.
const files = { pricing: "", contact: "" };
for (const name of Object.keys(files) as (keyof typeof files)[])
  files[name] = readFileSync(join(process.cwd(), "public/art", `${name}.svg`), "utf8");

export function Art({ name, className = "" }: { name: keyof typeof files; className?: string }) {
  return <div className={`art-scroll ${className}`} dangerouslySetInnerHTML={{ __html: files[name] }} />;
}

/** A moving band of display type. Decorative: the same words appear elsewhere as real content. */
export function Marquee({ items, variant }: { items: string[]; variant: "ticker" | "band" }) {
  const row = (
    <span className="marquee-row">
      {items.map((it, i) => (
        <span key={i} className={variant === "ticker" && i % 2 ? "outline-type" : undefined}>
          {it}
          <span className="marquee-sep">✦</span>
        </span>
      ))}
    </span>
  );
  const band = (
    <div className={`marquee marquee-${variant}`} aria-hidden>
      <div className="marquee-track display">
        {row}
        {row}
      </div>
    </div>
  );
  // The band is tilted, so it gets a clipping wrapper: its corners must not widen the page.
  return variant === "band" ? <div className="marquee-clip">{band}</div> : band;
}
